import 'package:flutter/material.dart';\r\nimport '../../screens/auth/login_screen.dart';\r\nimport '../../screens/auth/signup_screen.dart';\r\nimport '../../screens/auth/splash_screen.dart';\r\nimport '../../screens/customer/customer_main_scaffold.dart';\r\nimport '../../screens/staff/staff_main_scaffold.dart';\r\nimport '../../screens/admin/admin_main_scaffold.dart';\r\nimport '../../screens/staff/returning_customer_profile_screen.dart';\r\nimport '../../screens/booking/service_selection_screen.dart';\r\n\r\n/// Centralized named-route generator for the entire StyleHub app.\r\n///\r\n/// Routes are resolved by [MaterialApp.onGenerateRoute]; the root widget\r\n/// ([AuthWrapper]) uses direct widget returns instead of named routes.\r\nclass AppRouter {\r\n  static Route<dynamic> generateRoute(RouteSettings settings) {\r\n    switch (settings.name) {\r\n      case '/login':\r\n        return MaterialPageRoute(builder: (_) => const LoginScreen());\r\n      case '/signup':\r\n        return MaterialPageRoute(builder: (_) => const SignUpScreen());\r\n      case '/splash':\r\n        return MaterialPageRoute(builder: (_) => const SplashScreen());\r\n      case '/customer-home':\r\n        return MaterialPageRoute(builder: (_) => const CustomerMainScaffold());\r\n      case '/staff-home':\r\n        return MaterialPageRoute(builder: (_) => const StaffMainScaffold());\r\n      case '/admin-home':\r\n        return MaterialPageRoute(builder: (_) => const AdminMainScaffold());\r\n      case '/customer-profile':\r\n        final customerId = settings.arguments as String?;\r\n        return MaterialPageRoute(\r\n          builder: (_) => ReturningCustomerProfileScreen(\r\n            customerId: customerId ?? '',\r\n          ),\r\n        );\r\n      case '/service-selection':\r\n        return MaterialPageRoute(\r\n            builder: (_) => const ServiceSelectionScreen());\r\n      default:\r\n        return MaterialPageRoute(\r\n          builder: (_) => Scaffold(\r\n            body: Center(\r\n              child: Text('Route not found: ${settings.name}'),\r\n            ),\r\n          ),\r\n        );\r\n    }\r\n  }\r\n}\r\n
